// recapRepos ports recapRepos(): scoped → [repo]; else the user's repos ranked
// by checkpoint count desc with an alphabetical tiebreak. Repos are repo_id ULIDs.
func recapRepos(cps []store.MyActivityRow, scoped string) []string {
	if scoped != "" {
		return []string{scoped}
	}
	counts := map[string]int{}
	order := []string{}
	for _, r := range cps {
		if _, ok := counts[r.RepoID]; !ok {
			order = append(order, r.RepoID)
		}
		counts[r.RepoID]++
	}
	sort.SliceStable(order, func(i, j int) bool {
		if counts[order[i]] != counts[order[j]] {
			return counts[order[i]] > counts[order[j]]
		}
		return order[i] < order[j]
	})
	return order
}

// buildDailyActivity ports buildDailyActivity(): one UTC-day bucket per day in
// [start, end), each counting the user's checkpoints whose commit date lands on it.
func buildDailyActivity(cps []store.MyActivityRow, start, end time.Time) []meDailyCount {
	startDay := time.Date(start.UTC().Year(), start.UTC().Month(), start.UTC().Day(), 0, 0, 0, 0, time.UTC)
	endU := end.UTC()
	days := []string{}
	for cur := startDay; cur.Before(endU); cur = cur.AddDate(0, 0, 1) {
		days = append(days, cur.Format("2006-01-02"))
	}
	counts := make(map[string]int, len(days))
	for _, d := range days {
		counts[d] = 0
	}
	for _, r := range cps {
		d := r.CommittedAt.UTC().Format("2006-01-02")
		if _, ok := counts[d]; ok {
			counts[d]++
		}
	}

