77	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
78		// Clone the request to avoid mutating the caller's request.
79		r := req.Clone(req.Context())
80		if t.token != "" {
81			r.Header.Set("Authorization", "Bearer "+t.token)
82		}
83		r.Header.Set("User-Agent", versioninfo.UserAgent())
84		if r.Header.Get("Accept") == "" {
85			r.Header.Set("Accept", "application/json")
86		}
87		resp, err := t.base.RoundTrip(r)
88		if err != nil {
89			return nil, fmt.Errorf("round trip: %w", err)
90		}
91		return resp, nil
92	}
