package api

import (
	"fmt"
	"os"
	"strings"
)

// entire-api (the per-cell product / k8s aggregation API) is reached by filling
// three operator-supplied templates, mirroring entire.io/api's lib/entire-api
// (buildBaseUrl / buildAudience / buildCoreBaseUrl). Unlike the data API
// (BaseURL), entire-api is addressed per-cell and authenticated with a
// jurisdictional identity token whose audience is a separate value, so three
// templates are needed rather than one origin:
//
//   - ENTIRE_API_BASE_URL_TEMPLATE — the product-API host; {cell} is filled
//     from the target repo's mirror (e.g. https://{cell}.api.entire.io).
//   - ENTIRE_API_AUDIENCE_TEMPLATE — the jurisdictional identity-token audience
//     entire-api requires (a cell rejects a token minted for any other aud);
//     {jurisdiction} is filled from the same mirror (e.g.
//     https://{jurisdiction}.entire.io).
//   - ENTIRE_CORE_BASE_URL_TEMPLATE — the core that mints that token. A cell
//     only trusts a token signed by its own region's core, so {jurisdiction}
//     selects it (e.g. https://{jurisdiction}.auth.entire.io). Unset means a
//     single-core deployment: callers fall back to the active context's core.
const (
	// EntireAPIBaseURLTemplateEnvVar names the {cell} host template for entire-api.
	EntireAPIBaseURLTemplateEnvVar = "ENTIRE_API_BASE_URL_TEMPLATE"
	// EntireAPIAudienceTemplateEnvVar names the {jurisdiction} audience template.
	EntireAPIAudienceTemplateEnvVar = "ENTIRE_API_AUDIENCE_TEMPLATE"
	// EntireCoreBaseURLTemplateEnvVar names the {jurisdiction} token-minting core template.
	EntireCoreBaseURLTemplateEnvVar = "ENTIRE_CORE_BASE_URL_TEMPLATE"

	cellPlaceholder         = "{cell}"
	jurisdictionPlaceholder = "{jurisdiction}"
)

// EntireAPIBaseURLTemplate returns the trimmed ENTIRE_API_BASE_URL_TEMPLATE
// value (empty when unset). A non-empty value is what gates entire-api routing:
// callers treat an empty template as "entire-api not configured".
func EntireAPIBaseURLTemplate() string {
	return strings.TrimSpace(os.Getenv(EntireAPIBaseURLTemplateEnvVar))
}

// EntireAPIAudienceTemplate returns the trimmed ENTIRE_API_AUDIENCE_TEMPLATE
// value (empty when unset).
func EntireAPIAudienceTemplate() string {
	return strings.TrimSpace(os.Getenv(EntireAPIAudienceTemplateEnvVar))
}

// EntireCoreBaseURLTemplate returns the trimmed ENTIRE_CORE_BASE_URL_TEMPLATE
// value (empty when unset, meaning single-core: mint at the active core).
func EntireCoreBaseURLTemplate() string {
	return strings.TrimSpace(os.Getenv(EntireCoreBaseURLTemplateEnvVar))
}

// BuildEntireAPIBaseURL fills {cell} in an ENTIRE_API_BASE_URL_TEMPLATE value
// and strips trailing slashes, e.g.
//
//	BuildEntireAPIBaseURL("https://{cell}.api.entire.io", "aws-us-east-2")
//	  → "https://aws-us-east-2.api.entire.io"
//
// It errors when the template is empty, is missing the {cell} placeholder, or
// cell is empty: a silently-unsubstituted template would dial the wrong host.
func BuildEntireAPIBaseURL(template, cell string) (string, error) {
	return fillTemplate(EntireAPIBaseURLTemplateEnvVar, template, cellPlaceholder, cell)
}

// BuildEntireAPIAudience fills {jurisdiction} in an ENTIRE_API_AUDIENCE_TEMPLATE
// value and strips trailing slashes. Same error contract as
// BuildEntireAPIBaseURL: an empty or unsubstituted audience would mint a token
// entire-api rejects.
func BuildEntireAPIAudience(template, jurisdiction string) (string, error) {
	return fillTemplate(EntireAPIAudienceTemplateEnvVar, template, jurisdictionPlaceholder, jurisdiction)
}

// BuildEntireCoreBaseURL fills {jurisdiction} in an ENTIRE_CORE_BASE_URL_TEMPLATE
// value. An empty template returns fallback unchanged, so single-core
// deployments behave exactly as before (the active context's core mints the
// token). A set-but-broken template (missing placeholder / empty jurisdiction)
// still errors rather than silently minting at the wrong core.
func BuildEntireCoreBaseURL(template, jurisdiction, fallback string) (string, error) {
	if strings.TrimSpace(template) == "" {
		return fallback, nil
	}
	return fillTemplate(EntireCoreBaseURLTemplateEnvVar, template, jurisdictionPlaceholder, jurisdiction)
}

// fillTemplate substitutes every occurrence of placeholder with value in a
// non-empty template that contains it, then strips trailing slashes. envName is
// only used to make the error messages point at the offending operator setting.
func fillTemplate(envName, template, placeholder, value string) (string, error) {
	template = strings.TrimSpace(template)
	if template == "" {
		return "", fmt.Errorf("%s is not set", envName)
	}
	if !strings.Contains(template, placeholder) {
		return "", fmt.Errorf("%s %q is missing the %s placeholder", envName, template, placeholder)
	}
	if strings.TrimSpace(value) == "" {
		return "", fmt.Errorf("cannot fill %s in %s: value is empty", placeholder, envName)
	}
	return strings.TrimRight(strings.ReplaceAll(template, placeholder, value), "/"), nil
}

