			cell:     "aws-us-east-2",
			want:     "https://aws-us-east-2.api.entire.io",
		},
		{
			name:     "strips trailing slashes",
			template: "https://{cell}.api.entire.io//",
			cell:     "eu-1",
			want:     "https://eu-1.api.entire.io",
		},
		{
			name:     "empty template",
			template: "  ",
			cell:     "eu-1",
			wantErr:  "is not set",
		},
		{
			name:     "missing placeholder",
			template: "https://api.entire.io",
			cell:     "eu-1",
			wantErr:  "missing the {cell} placeholder",
		},
		{
			name:     "empty cell",
			template: "https://{cell}.api.entire.io",
			cell:     " ",
			wantErr:  "value is empty",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			got, err := BuildEntireAPIBaseURL(tt.template, tt.cell)
			assertTemplateResult(t, got, err, tt.want, tt.wantErr)
		})
	}
}

func TestBuildEntireAPIAudience(t *testing.T) {
	t.Parallel()

	got, err := BuildEntireAPIAudience("https://{jurisdiction}.entire.io/", "eu")
	assertTemplateResult(t, got, err, "https://eu.entire.io", "")

	if _, err := BuildEntireAPIAudience("https://fixed.entire.io", "eu"); err == nil {
		t.Fatal("BuildEntireAPIAudience with no placeholder = nil error, want error")
	}
}

func TestBuildEntireCoreBaseURL(t *testing.T) {
	t.Parallel()

	// Empty template → single-core fallback, returned unchanged.
	got, err := BuildEntireCoreBaseURL("", "eu", "https://auth.entire.io")
	assertTemplateResult(t, got, err, "https://auth.entire.io", "")

	// Set template → filled with jurisdiction.
	got, err = BuildEntireCoreBaseURL("https://{jurisdiction}.auth.entire.io/", "eu", "https://auth.entire.io")
	assertTemplateResult(t, got, err, "https://eu.auth.entire.io", "")

	// Set but broken template errors rather than falling back.
	if _, err := BuildEntireCoreBaseURL("https://auth.entire.io", "eu", "https://auth.entire.io"); err == nil {
		t.Fatal("BuildEntireCoreBaseURL with no placeholder = nil error, want error")
	}
}

func TestEntireAPITemplateEnvReaders(t *testing.T) {
	// Cannot t.Parallel(): mutates process env via t.Setenv.
	t.Setenv(EntireAPIBaseURLTemplateEnvVar, "  https://{cell}.api.entire.io  ")
	t.Setenv(EntireAPIAudienceTemplateEnvVar, "")

	if got := EntireAPIBaseURLTemplate(); got != "https://{cell}.api.entire.io" {
		t.Errorf("EntireAPIBaseURLTemplate() = %q, want trimmed value", got)
	}
	if got := EntireAPIAudienceTemplate(); got != "" {
		t.Errorf("EntireAPIAudienceTemplate() = %q, want empty when unset", got)
	}
}

func assertTemplateResult(t *testing.T, got string, err error, want, wantErr string) {
	t.Helper()

	if wantErr != "" {
		if err == nil {
			t.Fatalf("got nil error, want error containing %q", wantErr)
		}
		if !strings.Contains(err.Error(), wantErr) {
			t.Fatalf("error = %q, want it to contain %q", err.Error(), wantErr)
		}
		return
	}
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

